// Homelab incident log: poll Prometheus firing alerts and record only STATE
// TRANSITIONS (new outage / recovery) so the daily note is not spammed every poll.
// Dedup state lives in workflow static data (verified to persist across runs).
// Fingerprint collapses the multiple label-series Prometheus emits per alert down
// to one incident per alertname+namespace+pod+instance.
const TZ = 'Asia/Taipei';
const time = new Date().toLocaleTimeString('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit' });

const result = ($json.data && Array.isArray($json.data.result)) ? $json.data.result : [];
const current = {};
for (const r of result) {
  const m = r.metric || {};
  const fp = [m.alertname || '', m.namespace || '', m.pod || '', m.instance || ''].join('|');
  const where = m.namespace ? `${m.namespace}/${m.pod || m.instance || ''}` : (m.pod || m.instance || '');
  current[fp] = `**${m.alertname || 'alert'}**${where ? ' ' + where : ''} _(sev: ${m.severity || 'none'})_`;
}

const store = $getWorkflowStaticData('global');
const prev = store.firing || {};

const lines = [];
for (const fp of Object.keys(current)) {
  if (!(fp in prev)) lines.push(`- ${time} 🔴 down: ${current[fp]} #homelab-incident`);
}
for (const fp of Object.keys(prev)) {
  if (!(fp in current)) lines.push(`- ${time} 🟢 recovered: ${prev[fp]} #homelab-incident`);
}

store.firing = current;

if (!lines.length) { return []; }
return [{ json: { body: '\n' + lines.join('\n') } }];
